def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [[0] * 7 for _ in range(h)]

    # The 5 marks the starting column of the path.
    x = 0
    for r, row in enumerate(grid):
        for c, value in enumerate(row):
            if value == 5:
                x = c - 8
                out[r][x] = 5

    # The tiles are read down the left column, then down the right column.
    tiles = []
    for left in (0, 4):
        for top in range(0, h - 2, 4):
            colors = [
                grid[r][c]
                for r in range(top, min(top + 3, h))
                for c in range(left, min(left + 3, w))
                if grid[r][c] != 0
            ]
            if colors:
                tiles.append((colors[0], top))

    r = 1
    for color, _ in tiles:
        if color == 6:
            for rr in range(r, min(r + 2, h)):
                if 0 <= x < 7:
                    out[rr][x] = 6
            r += 2
        else:
            length = {1: 3, 2: 2, 3: 4}.get(color, 3)
            if color == 1:  # travel from left to right
                start = x
                x += length - 1
            else:           # travel from right to left
                start = x - length + 1
                x -= length - 1
            for c in range(start, start + length):
                if 0 <= c < 7 and r < h:
                    out[r][c] = color
            r += 1

    return out
